import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY || '' });
const MODEL_NAME = "gemini-3-flash-preview";

const getAiFooter = (extra?: string) => `

---
**Clinical Analysis Footer (Dynamic)**
*   **Generated on:** ${new Date().toLocaleString()}
${extra ? `*   **Context:** ${extra}\n` : ''}*   **Telemedicine Disclaimer:** This analysis is for informational purposes for the consulting physician and does not replace in-person clinical examination.
*   **AI-Generated Analysis Disclaimer:** This report is generated by AI through Kayra Clinical Intelligence. All findings must be clinically verified by a qualified medical professional before making any therapeutic decisions.`;

export async function getRepertoryInsights(symptoms: string, extra?: string) {
  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: `Analyze these symptoms from a homeopathic perspective: ${symptoms}`
    });
    return response.text + getAiFooter(extra);
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Failed to fetch AI insights. Please try again.";
  }
}

